  'circumflex branch of coronary artery': D('ramus circumflexus', 'Kalbin damarları', 'Sol koroner atardamarın kalbin sol kenarını dolanan dalı; sol kulakçık ve sol karıncığın yan-arka duvarını besler.'),
  'marginal branch of coronary artery': D('ramus marginalis', 'Kalbin damarları', 'Kalbin kenarı boyunca inen koroner dal.'),
  'posterolateral branch of coronary artery': D('ramus posterolateralis', 'Kalbin damarları', 'Sol karıncığın arka-yan duvarını besleyen koroner dal.'),
  'set of interventricular septal branches of coronary artery': D('rami interventriculares septales', 'Kalbin damarları', 'Karıncıklar arası bölmenin içine dalan küçük koroner dallar; iletim sistemini de besler.'),
  // ---- veins ----
