  'internal iliac vein': D('v. iliaca interna', 'Toplardamarlar', 'Leğen boşluğu organlarından gelen kanı toplar.'),
  'splenic vein': D('v. splenica', 'Toplardamarlar', 'Dalaktan gelen kanı taşır; üst mezenterik toplardamarla birleşerek kapı toplardamarını oluşturur.'),
  'superior mesenteric vein': D('v. mesenterica superior', 'Toplardamarlar', 'İnce bağırsaktan emilen besinleri taşıyan kanı toplar ve kapı toplardamarı yoluyla karaciğere götürür.'),
