  // ---- nervous ----
  'cerebellum': D('cerebellum', 'Beyin', 'Beyincik. Kasların uyumlu çalışmasını, denge ve vücut duruşunu sağlar; hareketlerin öğrenilmesinde rol oynar. Alkol en çok bu bölümü etkiler.'),
  'pons': D('pons', 'Beyin sapı', 'Beyin sapının orta bölümü; beyin ile beyincik arasında köprü kurar, solunumun ritmini düzenlemeye yardım eder.'),
