const ORDW = ['first', 'second', 'third', 'fourth', 'fifth', 'sixth', 'seventh', 'eighth', 'ninth', 'tenth', 'eleventh', 'twelfth'];
const ord = (w) => ORDW.indexOf(w) + 1;
const FAMILY = [
  [/^(\w+) cervical vertebra$/, (m) => D(`vertebra cervicalis C${ord(m[1])}`, 'Omurga', `${ord(m[1])}. boyun omuru. Boyun omurlarının enine çıkıntılarındaki deliklerden beyne giden omur atardamarı geçer; 7. boyun omurunun dikensi çıkıntısı ense altında elle hissedilir.`)],
  [/^(\w+) thoracic vertebra$/, (m) => D(`vertebra thoracica T${ord(m[1])}`, 'Omurga', `${ord(m[1])}. göğüs omuru. 12 göğüs omurunun her biri bir çift kaburgayla eklem yapar; uzun dikensi çıkıntıları aşağı doğru eğiktir.`)],
  [/^(\w+) lumbar vertebra$/, (m) => D(`vertebra lumbalis L${ord(m[1])}`, 'Omurga', `${ord(m[1])}. bel omuru. Bel omurları en çok ağırlık taşıyan, gövdesi en büyük omurlardır; bel fıtığı en sık L4-L5 ve L5-S1 arasında görülür.`)],
  [/^intervertebral disk/, () => D('discus intervertebralis', 'Omurga', 'Omurlar arası disk: dışta lifli halka (anulus fibrosus), içte jelimsi çekirdek (nucleus pulposus). Darbe emer ve omurgaya esneklik verir; çekirdeğin dışarı taşması fıtıktır.')],
  [/^(\w+) rib$/, (m) => D(`costa ${ord(m[1])}`, 'Göğüs kafesi', ord(m[1]) <= 7 ? `${ord(m[1])}. kaburga — gerçek kaburga: kendi kıkırdağıyla doğrudan göğüs kemiğine bağlanır.` : ord(m[1]) <= 10 ? `${ord(m[1])}. kaburga — yalancı kaburga: kıkırdağı üstteki kaburganın kıkırdağına katılarak göğüs kemiğine dolaylı bağlanır.` : `${ord(m[1])}. kaburga — serbest (yüzen) kaburga: ön ucu karın kaslarında serbest sonlanır.`)],
  [/^(\w+) costal cartilage$/, (m) => D(`cartilago costalis ${ord(m[1])}`, 'Göğüs kafesi', `${ord(m[1])}. kaburga kıkırdağı; hiyalin kıkırdaktan yapılmıştır ve göğüs kafesine solunumda esneklik kazandırır.`)],
  [/^(\w+) metacarpal bone$/, (m) => D(`os metacarpi ${ord(m[1])}`, 'El', `${ord(m[1])}. el tarak kemiği. Beş tarak kemiği avuç içinin iskeletini oluşturur; başları yumruk yapınca boğumları meydana getirir.`)],
  [/^(\w+) metatarsal bone$/, (m) => D(`os metatarsi ${ord(m[1])}`, 'Ayak', `${ord(m[1])}. ayak tarak kemiği. Beş metatarsal kemik ayak kemerlerini oluşturur; başları ayakta dururken yükü taşır.`)],
  [/^(proximal|middle|distal) phalanx of (thumb|index finger|middle finger|ring finger|little finger)$/, (m) => D(`phalanx ${m[1] === 'proximal' ? 'proximalis' : m[1] === 'middle' ? 'media' : 'distalis'} manus`, 'El', 'Parmak kemiği (falanks). Başparmakta iki, diğer parmaklarda üçer falanks vardır; elde toplam 14 falanks bulunur.')],
  [/^(proximal|middle|distal) phalanx of (big toe|second toe|third toe|fourth toe|little toe)$/, (m) => D(`phalanx ${m[1] === 'proximal' ? 'proximalis' : m[1] === 'middle' ? 'media' : 'distalis'} pedis`, 'Ayak', 'Ayak parmağı kemiği (falanks). Başparmakta iki, diğer parmaklarda üçer falanks vardır.')],
  [/incisor tooth$/, () => D('dens incisivus', 'Dişler', 'Kesici diş: tek köklü, keskin kenarlı; besini ısırıp keser. Yetişkinde her çenede 4 kesici diş bulunur.')],
  [/canine tooth$/, () => D('dens caninus', 'Dişler', 'Köpek dişi: en uzun köklü diştir; besini yırtar. Her çenede 2 tane bulunur.')],
  [/premolar tooth$/, () => D('dens premolaris', 'Dişler', 'Küçük azı dişi: iki tümsekli, besini ezip parçalar. Süt dişlerinde bulunmaz.')],
  [/molar tooth$/, () => D('dens molaris', 'Dişler', 'Büyük azı dişi: geniş çiğneme yüzeyli, çok köklü; besini öğütür. Üçüncü büyük azı "yirmilik dişi"dir. Yetişkinde toplam 32 diş vardır.')],
  [/gyrus|gyri|lobule/, () => D('gyrus cerebri', 'Beyin kabuğu', 'Beyin kabuğunun kıvrımlarından (girus) biri. Kıvrımlar ve aralarındaki oluklar (sulkus) kabuğun yüzey alanını yaklaşık üç katına çıkarır; kabuk gri maddeden (nöron gövdeleri) oluşur.')],
  [/commissure|stria|lamina terminalis|septum pellucidum|brachium of|capsule/, () => D('', 'Beyin · ak madde', 'Beynin bölgelerini birbirine bağlayan ak madde (miyelinli sinir lifi) yapısı.')],
  [/habenula|tuber cinereum|interpeduncular|interventricular foramen/, () => D('', 'Ara beyin', 'Ara beyin ve beyin karıncıkları çevresindeki küçük bir yapı.')],
];

// muscle fallbacks by wording of the English name
const MUSCLE_RULES = [
  [/rotator|interspinales|intertransvers|levatores costarum|semispinalis|spinalis|longissimus|iliocostalis|splenius|multifidus/, 'Derin sırt kasları', 'Omurgayı dik tutan ve omurlar arasında küçük hareketleri sağlayan derin sırt kaslarından biri.'],
  [/rectus capitis|obliquus capitis|longus capitis|longus colli/, 'Derin boyun kasları', 'Başı ve boynu omurga üzerinde dengeleyen derin boyun kaslarından biri.'],
  [/hyoid|thyroid/, 'Boyun kasları', 'Dil kemiği ve gırtlağı hareket ettirerek yutkunma ve konuşmaya katılan boyun kası.'],
  [/levator|depressor|nasalis|temporoparietalis/, 'Mimik kasları', 'Deriye tutunan mimik kaslarından biri; yüz sinirinin (VII) dalları tarafından uyarılır ve yüz ifadelerini oluşturur.'],
  [/lumbrical|interosse|opponens|digiti minimi|pollicis brevis|adductor pollicis|adductor hallucis|hallucis brevis|digitorum brevis|flexor accessorius/, 'El ve ayak kasları', 'El ya da ayağın içindeki küçük kaslardan biri; parmakların ince hareketlerini sağlar.'],
  [/flexor/, 'Bükücü kaslar', 'Bükücü (fleksör) kas: kasıldığında eklemi bükerek kemikleri birbirine yaklaştırır.'],
  [/extensor/, 'Açıcı kaslar', 'Açıcı (ekstansör) kas: kasıldığında eklemi açarak uzatır; bükücü kasların antagonistidir.'],
  [/abductor/, 'Uzaklaştırıcı kaslar', 'Uzaklaştırıcı (abduktör) kas: uzvu vücudun orta hattından uzaklaştırır.'],
  [/adductor/, 'Yaklaştırıcı kaslar', 'Yaklaştırıcı (addüktör) kas: uzvu vücudun orta hattına yaklaştırır.'],
  [/pronator|supinator/, 'Önkol kasları', 'Önkolu kendi ekseni etrafında döndürerek avuç içini aşağı ya da yukarı çeviren kas.'],
  [/gemellus|obturator|quadratus femoris/, 'Kalça kasları', 'Uyluğu dışa döndüren derin kalça kaslarından biri.'],
  [/oblique|transversus|rectus/, 'Gövde kasları', 'Gövdenin hareketine ve karın içi basıncın ayarlanmasına katılan kas.'],
];
function describe(p) {
  const base = p.base;
  if (DESC[base]) return DESC[base];
  for (const [re, fn] of FAMILY) { const m = base.match(re); if (m) return fn(m); }
  if (p.mat === 'muscle' || p.mat === 'tendon') {
    for (const [re, group, desc] of MUSCLE_RULES) if (re.test(base)) return D('', group, desc + ' İskelet kasları istemli çalışır ve çizgili kas liflerinden oluşur.');
    return D('', '', 'İskelet kası: kirişleriyle kemiklere tutunur, kasılarak eklemleri hareket ettirir. Çizgili kas liflerinden oluşur ve istemli çalışır.');
  }
  return D('', '', '');
}
